"""Algorithm 3: the scale-halving renormalisation tower and its fixed points.

Coarse-graining a lattice foam of Planck spacing l means observing it at spacing
2l: the branch locus shrinks from Lambda(l) = {l n : n in Z} to Lambda(2l).  The
routines below iterate that flow inside a finite observation window, detect
fixed points, and compute the limit of the tower.

Complexity: each step over a window of half-width W costs O(W / l) to enumerate
the sites, and the tower terminates (inside the window) after O(log(W / l))
steps because the site count halves each time.
"""

from __future__ import annotations

import math


def lattice_sites(spacing: float, window: float) -> set[float]:
    """Branch points of Lambda(spacing) inside [-window, window]."""
    if spacing == 0.0:
        return {0.0}
    kmax = int(math.floor(window / abs(spacing) + 1e-9))
    return {round(spacing * n, 9) for n in range(-kmax, kmax + 1)}


def rg_step(spacing: float) -> float:
    """One coarse-graining step of the physical flow."""
    return 2.0 * spacing


def is_fixed(spacing: float, window: float) -> bool:
    """Test Lambda(2l) == Lambda(l) inside the observation window."""
    return lattice_sites(rg_step(spacing), window) == lattice_sites(spacing, window)


def rg_tower(spacing: float, window: float, steps: int) -> list[tuple[float, int]]:
    """Return [(spacing at step k, number of branch points)] along the flow."""
    out: list[tuple[float, int]] = []
    s = spacing
    for _ in range(steps):
        out.append((s, len(lattice_sites(s, window))))
        s = rg_step(s)
    return out


def tower_limit(spacing: float, window: float, steps: int = 40) -> set[float]:
    """Intersection of all rescalings: the limiting branch locus."""
    inter: set[float] | None = None
    s = spacing
    for _ in range(steps):
        sites = lattice_sites(s, window)
        inter = sites if inter is None else (inter & sites)
        s = rg_step(s)
        if s != 0.0 and abs(s) > 2 * window:
            break
    return inter or set()


def metric_defect(branch_boundary_size: int, sheets: int = 2) -> int:
    """|S \\ int S| * (|iota|^2 - |iota|)."""
    return branch_boundary_size * (sheets * sheets - sheets)


if __name__ == "__main__":
    W = 16.0
    for s, count in rg_tower(0.25, W, 8):
        print(f"spacing {s:8.4f}: {count:4d} branch points in [-{W}, {W}]")
    print("fixed points:",
          {s: is_fixed(s, W) for s in (0.25, 0.5, 1.0, 2.0, 0.0)})
    lim = tower_limit(0.25, W)
    print("tower limit:", sorted(lim),
          "-> metric defect", metric_defect(len(lim)),
          "(non-Hausdorff: the flow never reaches smooth spacetime)")
